// Toma el (unico) ticket Nuevo devuelto por la busqueda (range=0-0 = limit 1).
// Si no hay ningun ticket en estado Nuevo, devuelve 0 items y el flujo no procesa nada en esta corrida.
const data = $json.data || [];
return data.map(row => ({ json: { ticket_id: row['2'] } }));

// El content de GLPI viene con las etiquetas HTML escapadas como entidades
// (&lt;img src=&quot;...&quot;&gt; en vez de <img src="...">). Hay que decodificar
// ANTES de buscar <img>, si no el regex nunca encuentra nada.
function decodeEntities(str) {
  return str
    .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&nbsp;/g, ' ');
}

const ticket = $('GLPI - Detalle Ticket').first().json;
let html = ticket.content || '';
html = decodeEntities(html);
html = decodeEntities(html); // GLPI a veces escapa doble

const items = [];

// Solo el src de tags <img>, no cualquier link a documento que tambien tenga docid=
const imgTags = [...html.matchAll(/<img[^>]+src=["']([^"']+)["']/gi)].map(m => m[1]);
const docidSet = new Set();
for (const src of imgTags) {
  const m = src.match(/docid=(\d+)/);
  if (m) docidSet.add(m[1]);
}
for (const id of docidSet) {
  items.push({ ticket_id: ticket.id, tipo: 'docid', docid: id, tiene_imagen: true });
}

const inlineMatches = [...html.matchAll(/<img[^>]+src=["']data:(image\/[a-zA-Z0-9.+-]+);base64,([A-Za-z0-9+\/=\s]+)["']/gi)];
inlineMatches.forEach((m) => {
  items.push({
    ticket_id: ticket.id,
    tipo: 'inline',
    docid: null,
    imagen_base64: m[2].replace(/\s+/g, ''),
    imagen_mime_declarado: m[1],
    tiene_imagen: true,
  });
});

if (items.length === 0) {
  return [{ json: { ticket_id: ticket.id, docid: null, tipo: null, tiene_imagen: false }, pairedItem: { item: 0 } }];
}

return items.map(it => ({ json: it, pairedItem: { item: 0 } }));

// Procesa TODOS los items de entrada (una respuesta de Abacus por item).
return $input.all().map(item => {
  let contenido = '';
  try {
    const resp = JSON.parse(item.json.abacus_raw);
    contenido = (resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
  } catch (e) {
    contenido = '[No se pudo interpretar la respuesta de Abacus: ' + String(item.json.abacus_raw).slice(0, 300) + ']';
  }
  return {
    json: {
      ticket_id: item.json.ticket_id,
      docid: item.json.docid,
      tiene_imagen: true,
      analisis_imagen: contenido,
    }
  };
});

return $input.all().map(item => ({
  json: {
    ticket_id: item.json.ticket_id,
    docid: null,
    tiene_imagen: false,
    analisis_imagen: '',
  }
}));

// Todos estos items pertenecen al mismo ticket (Loop Tickets procesa de a uno).
// pairedItem: 0 explicito para no perder el linaje hacia el ticket original.
const items = $input.all();
const partes = items
  .filter(i => i.json.tiene_imagen && i.json.analisis_imagen)
  .map((i, idx) => `Imagen ${idx + 1}:\n${i.json.analisis_imagen}`);

return [{
  json: { analisis_imagenes: partes.length ? partes.join('\n\n') : '' },
  pairedItem: { item: 0 },
}];

// Toma el HTML del ticket + el analisis de imagenes ya generado por Abacus.
const ticket = $('GLPI - Detalle Ticket').first().json;
let html = ticket.content || '';

function decodeEntities(str) {
  return str
    .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&nbsp;/g, ' ')
    .replace(/&aacute;/gi, 'a').replace(/&eacute;/gi, 'e').replace(/&iacute;/gi, 'i').replace(/&oacute;/gi, 'o').replace(/&uacute;/gi, 'u')
    .replace(/&ntilde;/gi, 'n');
}

html = decodeEntities(html);
html = decodeEntities(html);

// Las imagenes ya fueron analizadas por Abacus; solo dejamos una referencia en el texto.
html = html.replace(/<img[^>]*>/gi, '[Imagen - ver analisis extraido abajo]');

html = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
           .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');

html = html.replace(/<br\s*\/?\s*>/gi, '\n')
           .replace(/<\/p>/gi, '\n\n')
           .replace(/<\/li>/gi, '\n')
           .replace(/<\/div>/gi, '\n');

let texto = html.replace(/<[^>]+>/g, '');
texto = texto.replace(/[ \t]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n').trim();

const documentos = $('GLPI - Documentos Ticket').all();
const nombresAdjuntos = documentos
  .map(d => d.json.name || d.json.filename)
  .filter(Boolean);

const analisisImagenes = $json.analisis_imagenes || '';
const textoFinal = analisisImagenes
  ? `${texto}\n\nDetalles Adicionales:\n${analisisImagenes}`
  : texto;

return [{
  json: {
    ticket_id: ticket.id,
    texto_limpio: textoFinal,
    adjuntos: nombresAdjuntos.length ? nombresAdjuntos.join(', ') : 'sin adjuntos',
  }
}];

// IMPORTANTE: cuando n8n tiene el binary data en modo 'filesystem',
// item.binary.data.data NO trae el base64 real - trae un marcador interno
// (ej. 'filesystem-v2'). Hay que resolver el buffer real con el helper oficial
// this.helpers.getBinaryDataBuffer(itemIndex, propertyName), que funciona
// sin importar el modo de almacenamiento configurado.

function detectMime(b) {
  if (b.length >= 8 && b[0]===0x89 && b[1]===0x50 && b[2]===0x4E && b[3]===0x47) return 'image/png';
  if (b.length >= 3 && b[0]===0xFF && b[1]===0xD8 && b[2]===0xFF) return 'image/jpeg';
  if (b.length >= 4 && b.slice(0,3).toString('ascii') === 'GIF') return 'image/gif';
  if (b.length >= 12 && b.slice(0,4).toString('ascii') === 'RIFF' && b.slice(8,12).toString('ascii') === 'WEBP') return 'image/webp';
  if (b.length >= 2 && b[0]===0x42 && b[1]===0x4D) return 'image/bmp';
  return null;
}

const items = $input.all();
const abacusModel = $('Configuracion').first().json.abacus_model;
const promptTexto = "Extrae los datos de este formulario o pantalla como pares campo: valor, uno por linea, en texto plano. No uses JSON ni markdown ni explicaciones adicionales. Incluye todos los campos visibles (Organizacion, Tipo de documento, N. de documento, Factura, Tarifa, Fecha de pago, Totales, Moneda, etc). Si un campo esta vacio, en cero o resaltado en amarillo, indicalo explicitamente.";

const resultados = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary || !item.binary.data) {
    throw new Error('No se encontro binario "data" en el item - revisa GLPI - Descargar Imagen');
  }

  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const base64Real = buf.toString('base64');
  const mimeDetectado = detectMime(buf);
  const mimeFinal = mimeDetectado || item.binary.data.mimeType || null;
  const esGif = mimeFinal === 'image/gif';
  const soportado = !!mimeFinal && !esGif;

  const body = soportado ? {
    model: abacusModel,
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: promptTexto },
        { type: 'image_url', image_url: { url: 'data:' + mimeFinal + ';base64,' + base64Real } }
      ]
    }]
  } : null;

  resultados.push({
    json: {
      ...item.json,
      imagen_mime: mimeFinal,
      imagen_formato_soportado: soportado,
      abacus_request_body: soportado ? JSON.stringify(body) : null,
    },
    binary: item.binary,
  });
}

return resultados;

// Se descarta cada imagen de formato no soportado sin aportar texto,
// pero SIN perder las demas (procesa todos los items de entrada).
return $input.all().map(item => ({
  json: {
    ticket_id: item.json.ticket_id,
    docid: item.json.docid,
    tiene_imagen: false,
    analisis_imagen: '',
  }
}));

// Procesa TODOS los items de entrada. La imagen ya vino en base64 dentro del HTML.
// Regla de negocio: se soporta CUALQUIER tipo de imagen, EXCEPTO gif.
function detectMime(b) {
  if (b.length >= 8 && b[0]===0x89 && b[1]===0x50 && b[2]===0x4E && b[3]===0x47) return 'image/png';
  if (b.length >= 3 && b[0]===0xFF && b[1]===0xD8 && b[2]===0xFF) return 'image/jpeg';
  if (b.length >= 4 && b.slice(0,3).toString('ascii') === 'GIF') return 'image/gif';
  if (b.length >= 12 && b.slice(0,4).toString('ascii') === 'RIFF' && b.slice(8,12).toString('ascii') === 'WEBP') return 'image/webp';
  if (b.length >= 2 && b[0]===0x42 && b[1]===0x4D) return 'image/bmp';
  return null;
}

function limpiarBase64(s) {
  // por si viene con prefijo 'data:...;base64,' pegado por error
  const idx = s.indexOf('base64,');
  return idx >= 0 ? s.slice(idx + 7) : s;
}

return $input.all().map(item => {
  const base64Original = item.json.imagen_base64;
  if (!base64Original) {
    throw new Error('Imagen inline sin base64 - revisar Extraer Imagenes (docids)');
  }
  const base64Limpio = limpiarBase64(base64Original);
  const buf = Buffer.from(base64Limpio, 'base64');
  const mimeDetectado = detectMime(buf);
  const mimeFinal = mimeDetectado || item.json.imagen_mime_declarado || null;
  const esGif = mimeFinal === 'image/gif';

  const abacusModel = $('Configuracion').first().json.abacus_model;
  const promptTexto = "Extrae los datos de este formulario o pantalla como pares campo: valor, uno por linea, en texto plano. No uses JSON ni markdown ni explicaciones adicionales. Incluye todos los campos visibles (Organizacion, Tipo de documento, N. de documento, Factura, Tarifa, Fecha de pago, Totales, Moneda, etc). Si un campo esta vacio, en cero o resaltado en amarillo, indicalo explicitamente.";
  const body = {
    model: abacusModel,
    messages: [
      {
        role: 'user',
        content: [
          { type: 'text', text: promptTexto },
          { type: 'image_url', image_url: { url: 'data:' + mimeFinal + ';base64,' + base64Limpio } }
        ]
      }
    ]
  };
  return {
    json: {
      ...item.json,
      imagen_mime: mimeFinal,
      imagen_formato_soportado: !!mimeFinal && !esGif,
      abacus_request_body: (!!mimeFinal && !esGif) ? JSON.stringify(body) : null,
    },
  };
});
